import 'dart:convert';import 'dart:typed_data';import 'package:flutter/services.dart';import 'package:nfc_manager/ndef_record.dart';import 'package:nfc_manager/nfc_manager.dart';import 'package:nfc_manager/src/nfc_manager_ios/nfc_manager.dart';import 'package:nfc_manager_ndef/nfc_manager_ndef.dart';class NfcService  {  NfcService._();  static final NfcService instance = NfcService._();  Future<bool> isAvailable() {   return NfcManager.instance.isAvailable();  }  Future<void> startSession({ required void Function(NfcTag p1) onDiscovered, String? alertMessageIos, bool invalidateAfterFirstReadIos = true, void Function(NfcReaderSessionErrorIos p1)? onSessionErrorIos, bool noPlatformSoundsAndroid = false}) {    return NfcManager.instance.startSession(      pollingOptions: {NfcPollingOption.iso14443, NfcPollingOption.iso15693, NfcPollingOption.iso18092},      onDiscovered: onDiscovered,      alertMessageIos: alertMessageIos,      invalidateAfterFirstReadIos: invalidateAfterFirstReadIos,      onSessionErrorIos: onSessionErrorIos,      noPlatformSoundsAndroid: noPlatformSoundsAndroid,    );  }  /// Oturum kullanıcı iptali, zaman aşımı veya iOS tarafından zaten  /// kapatılmışsa `no_active_sessions` hatası yutulur.  Future<void> stopSession({String? alertMessageIos, String? errorMessageIos}) async {    try {      await NfcManager.instance.stopSession(alertMessageIos: alertMessageIos, errorMessageIos: errorMessageIos);    } on PlatformException catch (e) {      if (e.code != 'no_active_sessions') rethrow;    }  }  /// Text (well-known, RTD 'T') kaydı oluşturur.  /// [text] = gösterilecek metin  /// [languageCode] = örn "en" veya "tr"  /// [useUtf16] = false ise UTF-8, true ise UTF-16 kullanır.  NdefRecord createTextRecord({    required String text,    String languageCode = 'en',    bool useUtf16 = false,  }) {    // status byte: bit7 = encoding (0 = UTF-8, 1 = UTF-16)    // bit6..0 = length of language code    final langBytes = utf8.encode(languageCode);    final textBytes = useUtf16 ? utf8.encode(text) /* basit tercih: normalde UTF-16 için farklı kodlama gerekir */ : utf8.encode(text);    final status = (useUtf16 ? 0x80 : 0x00) | (langBytes.length & 0x3F);    final payload = <int>[status, ...langBytes, ...textBytes];    return NdefRecord(      typeNameFormat: TypeNameFormat.wellKnown,      type: Uint8List.fromList([0x54]), // 'T'      identifier: Uint8List(0),      payload: Uint8List.fromList(payload),    );  }  /// URI (well-known, RTD 'U') kaydı oluşturur.  /// [uri] = örn "https://example.com/path"  /// [prefixCode] standard URI identifier code (0x00 none). Genelde 0x00 ile çalışır.  NdefRecord createUriRecord({    required String uri,    int prefixCode = 0x00,  }) {    final uriBytes = utf8.encode(uri);    final payload = <int>[prefixCode, ...uriBytes];    return NdefRecord(      typeNameFormat: TypeNameFormat.wellKnown,      type: Uint8List.fromList([0x55]), // 'U'      identifier: Uint8List(0),      payload: Uint8List.fromList(payload),    );  }  /// MIME (media) kaydı oluşturur.  /// [mimeType] örn "text/vcard" veya "image/png"  /// [data] payload olarak gönderilecek ham byte'lar  NdefRecord createMimeRecord({    required String mimeType,    required Uint8List data,  }) {    return NdefRecord(      typeNameFormat: TypeNameFormat.media,      type: _u8(mimeType),      identifier: Uint8List(0),      payload: data,    );  }  /// External type kaydı oluşturur (TNF = external).  /// [domainAndType] örn "example.com:mytype"  /// [data] payload  NdefRecord createExternalRecord({    required String domainAndType,    required Uint8List data,  }) {    return NdefRecord(      typeNameFormat: TypeNameFormat.external,      type: _u8(domainAndType),      identifier: Uint8List(0),      payload: data,    );  }  /// Absolute-URI kaydı oluşturur (TNF = absoluteUri).  /// RFC'ye göre 'type' alanı mutlak URI içerir, payload ise veri.  /// [uri] örn "https://example.com/resource"  NdefRecord createAbsoluteUriRecord({    required String uri,    required Uint8List payload,  }) {    return NdefRecord(      typeNameFormat: TypeNameFormat.absoluteUri,      type: _u8(uri),      identifier: Uint8List(0),      payload: payload,    );  }  /// EMPTY kaydı (TNF = empty) - tüm alanlar boş olmalı.  NdefRecord createEmptyRecord() {    return NdefRecord(      typeNameFormat: TypeNameFormat.empty,      type: Uint8List(0),      identifier: Uint8List(0),      payload: Uint8List(0),    );  }  Uint8List _u8(String s) => Uint8List.fromList(utf8.encode(s));}